// Town builds for /place: a dense downtown (`city`) and two schools —
// `small_school` (4 classrooms on one floor) and `large_school` (3 floors of 4
// with a stair tower). Same conventions as the other starter structures:
// (x, y, z) is the north-west corner, y the first air layer, floors at y - 1,
// and fronts face north (−z). Never generated by worldgen.

import Foundation

@inline(__always) private func N(_ name: String, _ m: Int = 0) -> Int { Int(cell(bid(name), m)) }
private let AIR = 0

/// a wall sign (up to 4 lines, "|" between them). `meta` is the wall it hangs
/// on: 0 = the block to the south (sign faces north), 1 = north, 2 = east, 3 = west
func wallSign(_ b: Builder, _ x: Int, _ y: Int, _ z: Int, _ meta: Int, _ text: String) {
    b.set(x, y, z, N("oak_wall_sign", meta))
    b.s.addBlockEntity(BESpec(x: x, y: y, z: z, kind: "sign", data: ["text": .str(text)]))
}

// ---------------------------------------------------------------------------
// Schools
// ---------------------------------------------------------------------------
/// floor slab + 4 air
private let STORY = 5

func starterSmallSchool(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    school(b, x, y, z, floors: 1, sign: "|Pebble|Elementary|")
}
func starterLargeSchool(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    school(b, x, y, z, floors: 3, sign: "|Pebble High|School|")
}

/// two rows of classrooms either side of a hallway that runs back from the
/// front door, 4 rooms per floor; more than one floor adds a stair tower
/// at the back of the hallway
private func school(_ b: Builder, _ x: Int, _ y: Int, _ z: Int, floors: Int, sign: String) {
    let outer = floors > 1 ? N("bricks") : N("white_terracotta")
    let trim = N("stone_bricks"), inner = N("white_concrete"), board = N("black_concrete")
    let roomFloor = N("oak_planks"), hallFloor = N("smooth_stone"), win = N("glass_pane")
    let light = N("glowstone")
    let RW = 10, RD = 9, HW = 5                       // room width (x), room depth (z), hall width
    let W = 1 + RW + 1 + HW + 1 + RW + 1               // 29
    let D = 1 + RD + 1 + RD + 1                        // 21
    let x1 = x + W - 1, z1 = z + D - 1
    let hx0 = x + 1 + RW + 1, hx1 = hx0 + HW - 1       // hall interior
    let zp = z + 1 + RD                                // wall between the north and south rooms
    let tower = floors > 1
    let tz1 = tower ? z1 + 7 : z1                      // stair tower: interior z1...z1+6
    let roof = y - 1 + floors * STORY
    let rooms = [(x + 1, true), (hx1 + 2, true), (x + 1, false), (hx1 + 2, false)]  // (west x, north row?)

    // clear the lot, then the shell
    b.fill(x - 3, y, z - 5, x1 + 3, roof + 3, tz1 + 3, AIR)
    b.fill(x, y - 1, z, x1, roof, z1, outer)
    if tower { b.fill(hx0 - 1, y - 1, z1, hx1 + 1, roof, tz1, outer) }
    for f in 0..<floors {
        let fy = y + f * STORY
        // interior
        b.fill(x + 1, fy, z + 1, x1 - 1, fy + 3, z1 - 1, AIR)
        b.fill(x + 1, fy - 1, z + 1, x1 - 1, fy - 1, z1 - 1, roomFloor)
        b.fill(hx0, fy - 1, z + 1, hx1, fy - 1, z1 - 1, hallFloor)
        // inner walls: the hall's two sides and the wall between room rows
        b.fill(hx0 - 1, fy, z + 1, hx0 - 1, fy + 3, z1 - 1, inner)
        b.fill(hx1 + 1, fy, z + 1, hx1 + 1, fy + 3, z1 - 1, inner)
        b.fill(x + 1, fy, zp, hx0 - 2, fy + 3, zp, inner)
        b.fill(hx1 + 2, fy, zp, x1 - 1, fy + 3, zp, inner)
        // floor band on the outside
        b.fill(x, fy - 1, z, x1, fy - 1, z, trim)
        b.fill(x, fy - 1, z1, x1, fy - 1, z1, trim)
        b.fill(x, fy - 1, z, x, fy - 1, z1, trim)
        b.fill(x1, fy - 1, z, x1, fy - 1, z1, trim)
        // windows: pairs along every outside wall of the rooms
        for wy in (fy + 1)...(fy + 2) {
            for d in stride(from: 2, to: RW, by: 3) {
                for rx in [x + 1, hx1 + 2] {
                    b.set(rx + d, wy, z, win); b.set(rx + d + 1, wy, z, win)
                    b.set(rx + d, wy, z1, win); b.set(rx + d + 1, wy, z1, win)
                }
            }
            for d in stride(from: 2, to: D - 2, by: 3) where z + d != zp && z + d + 1 != zp {
                b.set(x, wy, z + d, win); b.set(x, wy, z + d + 1, win)
                b.set(x1, wy, z + d, win); b.set(x1, wy, z + d + 1, win)
            }
        }
        // hall lights
        for lz in stride(from: z + 3, to: z1, by: 4) { b.set(hx0 + 2, fy + 4, lz, light) }
        for (rx, north) in rooms { classroom(b, rx, fy, z, zp, z1, RW, north: north, board: board, light: light) }
        // room doors off the hall, at the end away from the chalkboard
        door(b, hx0 - 1, fy, z + 2, 2)
        door(b, hx1 + 1, fy, z + 2, 3)
        door(b, hx0 - 1, fy, z1 - 2, 2)
        door(b, hx1 + 1, fy, z1 - 2, 3)
    }
    // flat roof with a stone-brick parapet
    b.fill(x, roof, z, x1, roof, z1, trim)
    for d in 0...(W - 1) { b.set(x + d, roof + 1, z, trim); b.set(x + d, roof + 1, z1, trim) }
    for d in 0...(D - 1) { b.set(x, roof + 1, z + d, trim); b.set(x1, roof + 1, z + d, trim) }

    // front entrance: door under a sign, glass either side, a path and a flag
    b.set(hx0 + 1, y, z, N("glass")); b.set(hx0 + 1, y + 1, z, N("glass"))
    b.set(hx0 + 3, y, z, N("glass")); b.set(hx0 + 3, y + 1, z, N("glass"))
    door(b, hx0 + 2, y, z, 0)
    wallSign(b, hx0 + 2, y + 2, z - 1, 0, sign)
    b.fill(hx0 + 1, y - 1, z - 5, hx0 + 3, y - 1, z - 1, hallFloor)
    b.set(hx0, y, z - 1, N("lantern")); b.set(hx0 + 4, y, z - 1, N("lantern"))
    flag(b, hx0 - 3, y, z - 4)

    if tower {
        stairTower(b, hx0, y, z1, floors: floors, trim: trim, light: light)
        b.fill(hx0 - 1, roof, z1, hx1 + 1, roof, tz1, trim)
    } else {
        door(b, hx0 + 2, y, z1, 1) // back door
    }
}

/// one classroom: chalkboard on the wall shared with the room across the
/// row, teacher's desk in front of it, 3 rows of 4 desks facing it
private func classroom(_ b: Builder, _ rx: Int, _ fy: Int, _ z: Int, _ zp: Int, _ z1: Int, _ RW: Int,
                       north: Bool, board: Int, light: Int) {
    // toward the board: +z for the north rooms, −z for the south rooms
    let s = north ? 1 : -1
    let desk = N("oak_slab", 1), chair = N("oak_stairs", north ? 0 : 1)
    for bx in (rx + 2)...(rx + 7) { b.set(bx, fy + 1, zp, board); b.set(bx, fy + 2, zp, board) }
    // teacher's desk and chair
    b.set(rx + 4, fy, zp - 2 * s, N("dark_oak_planks")); b.set(rx + 5, fy, zp - 2 * s, N("dark_oak_planks"))
    b.set(rx + 4, fy, zp - s, N("oak_stairs", north ? 1 : 0))
    b.set(rx + 5, fy + 1, zp - 2 * s, N("lantern"))
    // bookshelves either side of the board
    for bx in [rx, rx + RW - 1] { b.set(bx, fy, zp - s, N("bookshelf")); b.set(bx, fy + 1, zp - s, N("bookshelf")) }
    // student desks, chairs behind them
    for r in 0..<3 {
        let dz = zp - (4 + 2 * r) * s
        for sx in [rx + 1, rx + 3, rx + 6, rx + 8] {
            b.set(sx, fy, dz, desk)
            b.set(sx, fy, dz - s, chair)
        }
    }
    // ceiling lights
    for lx in [rx + 2, rx + RW - 3] {
        for lz in [zp - 3 * s, zp - 7 * s] { b.set(lx, fy + 4, lz, light) }
    }
}

/// switchback stairs behind the hall: interior x hx0...hx0+4, z t0...t0+6.
/// Lane A (west) climbs 3 south to a landing, lane B (east) climbs 2 north to
/// the next floor; a core wall splits the lanes
private func stairTower(_ b: Builder, _ hx0: Int, _ y: Int, _ t0: Int, floors: Int, trim: Int, light: Int) {
    let roof = y - 1 + floors * STORY
    let landing = N("smooth_stone")
    b.fill(hx0, y, t0, hx0 + 4, roof - 1, t0 + 6, AIR)
    b.fill(hx0 + 2, y, t0 + 2, hx0 + 2, roof - 1, t0 + 4, trim)          // core wall
    for f in 0..<floors {
        let fy = y + f * STORY
        if f > 0 {
            b.fill(hx0, fy - 1, t0, hx0 + 4, fy - 1, t0 + 1, landing)    // floor landing
            b.fill(hx0 + 3, fy - 1, t0 + 2, hx0 + 4, fy - 1, t0 + 2, landing)
        }
        b.set(hx0 + 2, fy + 3, t0 + 2, light)   // in the core wall
        if f == floors - 1 {
            // nothing further up: rail off the stairwell
            b.set(hx0, fy, t0 + 2, N("oak_fence")); b.set(hx0 + 1, fy, t0 + 2, N("oak_fence"))
            continue
        }
        for i in 0..<3 {
            for lx in hx0...(hx0 + 1) { b.set(lx, fy + i, t0 + 2 + i, N("stone_brick_stairs", 1)) }
        }
        b.fill(hx0, fy + 2, t0 + 5, hx0 + 4, fy + 2, t0 + 6, landing)    // half landing
        for j in 0..<2 {
            for lx in (hx0 + 3)...(hx0 + 4) { b.set(lx, fy + 3 + j, t0 + 4 - j, N("stone_brick_stairs", 0)) }
        }
    }
    // tower windows
    for f in 0..<floors {
        let fy = y + f * STORY
        b.set(hx0 - 1, fy + 2, t0 + 3, N("glass_pane")); b.set(hx0 + 5, fy + 2, t0 + 3, N("glass_pane"))
    }
}

// ---------------------------------------------------------------------------
// City
// ---------------------------------------------------------------------------
private let CITY_BLOCKS = 4
private let CITY_LOT = 18
private let CITY_STREET = 7

/// a 4×4 grid of city blocks on 7-wide streets: towers in the middle, lower
/// buildings at the edges, one block a park. `variant` reshuffles everything
func starterCity(_ b: Builder, _ x: Int, _ y: Int, _ z: Int) {
    let pitch = CITY_LOT + CITY_STREET
    let size = CITY_BLOCKS * CITY_LOT + (CITY_BLOCKS + 1) * CITY_STREET
    let x1 = x + size - 1, z1 = z + size - 1
    // the ground: hills inside the city are cut back, then asphalt everywhere
    b.fill(x, y, z, x1, y + 32, z1, AIR)
    b.fill(x, y - 1, z, x1, y - 1, z1, N("gray_concrete"))
    let line = N("yellow_concrete"), zebra = N("white_concrete")
    // dashed center lines between intersections
    for k in 0...CITY_BLOCKS {
        let mid = k * pitch + CITY_STREET / 2
        for d in 0..<size where d % pitch >= CITY_STREET && (d % pitch - CITY_STREET) % 4 < 2 {
            b.set(x + d, y - 1, z + mid, line)
            b.set(x + mid, y - 1, z + d, line)
        }
    }
    // crosswalks on every arm of every intersection
    for i in 0...CITY_BLOCKS {
        for j in 0...CITY_BLOCKS {
            let ix = x + i * pitch, iz = z + j * pitch
            for s in stride(from: 0, to: CITY_STREET, by: 2) {
                for d in 1...2 {
                    if iz - d >= z { b.set(ix + s, y - 1, iz - d, zebra) }
                    if iz + CITY_STREET - 1 + d <= z1 { b.set(ix + s, y - 1, iz + CITY_STREET - 1 + d, zebra) }
                    if ix - d >= x { b.set(ix - d, y - 1, iz + s, zebra) }
                    if ix + CITY_STREET - 1 + d <= x1 { b.set(ix + CITY_STREET - 1 + d, y - 1, iz + s, zebra) }
                }
            }
        }
    }
    let park = b.rng.nextInt(CITY_BLOCKS * CITY_BLOCKS)
    for j in 0..<CITY_BLOCKS {
        for i in 0..<CITY_BLOCKS {
            let lx = x + CITY_STREET + i * pitch, lz = z + CITY_STREET + j * pitch
            // sidewalk with a lamp on each corner
            b.fill(lx, y - 1, lz, lx + CITY_LOT - 1, y - 1, lz + CITY_LOT - 1, N("smooth_stone"))
            for (cx, cz) in [(lx, lz), (lx + CITY_LOT - 1, lz), (lx, lz + CITY_LOT - 1), (lx + CITY_LOT - 1, lz + CITY_LOT - 1)] {
                for py in y...(y + 2) { b.set(cx, py, cz, N("stone_brick_wall")) }
                b.set(cx, y + 3, cz, N("lantern"))
            }
            if j * CITY_BLOCKS + i == park {
                cityPark(b, lx + 2, y, lz + 2, CITY_LOT - 4)
                continue
            }
            // taller toward the middle of town
            let center = Double(CITY_BLOCKS - 1) / 2
            let edge = max(abs(Double(i) - center), abs(Double(j) - center)) / center   // 0 middle … 1 edge
            let lo = Int(56 - 34 * edge), hi = Int(92 - 46 * edge)
            let floors = max(4, b.rng.nextIntBetween(lo, hi) / 4)
            cityBuilding(b, lx + 2, y, lz + 2, CITY_LOT - 4, floors: floors, style: b.rng.nextInt(4))
        }
    }
}

/// one building: `style` 0 glass tower, 1 brick, 2 stone office, 3 white modern.
/// Lit floors every 4 blocks, storefront glass and doors at street level, a
/// ladder up through every floor to the roof
private func cityBuilding(_ b: Builder, _ bx: Int, _ y: Int, _ bz: Int, _ w: Int, floors: Int, style: Int) {
    let h = floors * 4
    let x1 = bx + w - 1, z1 = bz + w - 1
    let roof = y - 1 + h
    let glassColor = ["light_blue_stained_glass", "cyan_stained_glass", "gray_stained_glass"][(bx / 7 + bz / 3) % 3]
    let frame: Int, fill: Int, glass: Int
    switch style {
    case 0: frame = N("light_gray_concrete"); fill = N(glassColor); glass = N(glassColor)
    case 1: frame = N("stone_bricks"); fill = N("bricks"); glass = N("glass_pane")
    case 2: frame = N("stone_bricks"); fill = N("polished_andesite"); glass = N("glass")
    default: frame = N("white_concrete"); fill = N("white_concrete"); glass = N("black_stained_glass")
    }
    let slab = N("smooth_stone"), lamp = N("sea_lantern")
    // shell, one cell at a time
    for yy in (y - 1)...roof {
        let ry = yy - y
        for d in 0..<w {
            for (px, pz) in [(bx + d, bz), (bx + d, z1), (bx, bz + d), (x1, bz + d)] {
                let col = px == bx || px == x1 ? pz - bz : px - bx
                let corner = (px == bx || px == x1) && (pz == bz || pz == z1)
                var c: Int
                if corner || ry < 0 || ry % 4 == 3 {
                    c = frame                                     // corners and floor bands
                } else if ry < 3 {
                    c = col % 4 == 0 ? frame : N("glass")         // storefront
                } else {
                    switch style {
                    case 0: c = col % 4 == 0 ? frame : glass
                    case 1: c = col % 3 != 0 && ry % 4 != 0 ? glass : fill
                    case 2: c = col % 2 == 1 ? glass : frame
                    default: c = ry % 4 == 0 ? fill : (col % 5 == 0 ? fill : glass)
                    }
                }
                b.set(px, yy, pz, c)
            }
        }
    }
    // floors, lit from the ceiling; a ladder hole in the north-east corner
    let ladderX = x1 - 1, ladderZ = z1 - 1
    for f in 0...floors {
        let sy = y - 1 + f * 4
        b.fill(bx + 1, sy, bz + 1, x1 - 1, sy, z1 - 1, f == floors ? frame : slab)
        if f > 0 {
            for lx in stride(from: bx + 3, through: x1 - 3, by: 4) {
                for lz in stride(from: bz + 3, through: z1 - 3, by: 4) { b.set(lx, sy, lz, lamp) }
            }
        }
        if f < floors { b.fill(bx + 1, sy + 1, bz + 1, x1 - 1, sy + 3, z1 - 1, AIR) }
    }
    for ly in y...roof {
        b.set(ladderX, ly, ladderZ, N("ladder", 0))
    }
    // doors front and back, a sign by the front one
    door(b, bx + w / 2, y, bz, 0)
    door(b, bx + w / 2, y, z1, 1)
    b.set(bx + w / 2 - 1, y + 2, bz, frame)
    b.set(bx + w / 2 + 1, y + 2, bz, frame)
    // parapet and rooftop
    for d in 0..<w {
        for (px, pz) in [(bx + d, bz), (bx + d, z1), (bx, bz + d), (x1, bz + d)] { b.set(px, roof + 1, pz, frame) }
    }
    let mx = bx + w / 2, mz = bz + w / 2
    switch style {
    case 0:
        // a setback crown and an antenna with a beacon light
        let cw = w - 6
        let top = roof + 1 + b.rng.nextIntBetween(4, 10)
        b.fill(bx + 3, roof + 1, bz + 3, bx + 2 + cw, top, bz + 2 + cw, glass)
        b.fill(bx + 3, top + 1, bz + 3, bx + 2 + cw, top + 1, bz + 2 + cw, frame)
        let tip = top + 2 + b.rng.nextIntBetween(6, 14)
        for ay in (top + 2)..<tip { b.set(mx, ay, mz, N("iron_bars")) }
        b.set(mx, tip, mz, N("glowstone"))
    case 1:
        // water tower on legs
        for (lx, lz) in [(mx - 1, mz - 1), (mx + 1, mz - 1), (mx - 1, mz + 1), (mx + 1, mz + 1)] {
            for ly in (roof + 1)...(roof + 3) { b.set(lx, ly, lz, N("oak_fence")) }
        }
        b.fill(mx - 1, roof + 4, mz - 1, mx + 1, roof + 7, mz + 1, N("spruce_planks"))
        b.fill(mx - 1, roof + 8, mz - 1, mx + 1, roof + 8, mz + 1, N("spruce_slab"))
    case 2:
        // air-conditioning units and a stair house
        for (ux, uz) in [(bx + 2, bz + 2), (x1 - 3, bz + 2), (bx + 2, z1 - 4)] {
            b.fill(ux, roof + 1, uz, ux + 1, roof + 1, uz + 1, N("iron_block"))
            b.set(ux, roof + 2, uz, N("iron_trapdoor"))
        }
        b.fill(ladderX - 1, roof + 1, ladderZ - 1, ladderX + 1, roof + 3, ladderZ + 1, frame)
        b.fill(ladderX, roof + 1, ladderZ, ladderX, roof + 2, ladderZ, AIR)
        b.set(ladderX, roof + 1, ladderZ - 1, AIR); b.set(ladderX, roof + 2, ladderZ - 1, AIR)
    default:
        // rooftop garden
        b.fill(bx + 2, roof + 1, bz + 2, x1 - 2, roof + 1, z1 - 2, N("grass_block"))
        for _ in 0..<6 {
            let gx = b.rng.nextIntBetween(bx + 2, x1 - 2), gz = b.rng.nextIntBetween(bz + 2, z1 - 2)
            b.set(gx, roof + 2, gz, N(b.rng.nextBoolean() ? "oak_leaves" : "poppy"))
        }
    }
}

/// grass, paths, trees, benches and a fountain in the middle
private func cityPark(_ b: Builder, _ px: Int, _ y: Int, _ pz: Int, _ w: Int) {
    let x1 = px + w - 1, z1 = pz + w - 1, mx = px + w / 2, mz = pz + w / 2
    b.fill(px, y - 1, pz, x1, y - 1, z1, N("grass_block"))
    b.fill(mx - 1, y - 1, pz, mx, y - 1, z1, N("gravel"))
    b.fill(px, y - 1, mz - 1, x1, y - 1, mz, N("gravel"))
    // fountain
    b.fill(mx - 3, y - 1, mz - 3, mx + 2, y, mz + 2, N("stone_bricks"))
    b.fill(mx - 2, y, mz - 2, mx + 1, y, mz + 1, N("water"))
    b.fill(mx - 1, y, mz - 1, mx, y + 2, mz, N("quartz_block"))
    b.fill(mx - 1, y + 3, mz - 1, mx, y + 3, mz, N("water"))
    // a tree in each quarter
    for (tx, tz) in [(px + 2, pz + 2), (x1 - 2, pz + 2), (px + 2, z1 - 2), (x1 - 2, z1 - 2)] {
        b.fill(tx - 2, y + 3, tz - 2, tx + 2, y + 4, tz + 2, N("oak_leaves"))
        b.fill(tx - 1, y + 5, tz - 1, tx + 1, y + 5, tz + 1, N("oak_leaves"))
        for ty in y...(y + 4) { b.set(tx, ty, tz, N("oak_log")) }
    }
    // benches facing the fountain, flowers around the edges
    for bx in [mx - 3, mx - 2, mx + 1, mx + 2] {
        b.set(bx, y, mz - 5, N("oak_stairs", 0))
        b.set(bx, y, mz + 4, N("oak_stairs", 1))
    }
    for d in stride(from: 1, to: w - 1, by: 3) {
        b.set(px + d, y, pz, N(d % 2 == 0 ? "poppy" : "dandelion"))
        b.set(px + d, y, z1, N(d % 2 == 0 ? "dandelion" : "poppy"))
    }
}
